import{z as d,x as B,o as s,c as i,q as n,j as t,D as A,d as e,s as r,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"对齐与非对齐访问","description":"","frontmatter":{"title":"对齐与非对齐访问","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alignment-access.md","filePath":"cs/alignment-access.md","lastUpdated":1791063341000}'),p={name:"cs/alignment-access.md"};function c(C,a,D,m,S,I){const o=B("Mermaid");return s(),i("div",null,[a[2]||(a[2]=n('<h1 id="对齐与非对齐访问" tabindex="-1">对齐与非对齐访问 <a class="header-anchor" href="#对齐与非对齐访问" aria-label="Permalink to &quot;对齐与非对齐访问&quot;">​</a></h1><div class="epigraph"><p>自然对齐让一次访存落在单次总线事务与单次缓存行内；非对齐或被硬件拆成两拍，或 trap 到固件，原子与 SIMD 往往更严。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/endianness">上一课</a>钉了字节在字内的次序。次序假定「这一次 load 读的就是那四个字节」。缺口是 <strong>对齐</strong>：地址是否为宽度的倍数，以及 ISA 对违规的态度——硬件修复、异常，还是原子直接拒绝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自然对齐：<code>N</code> 字节对象要求 <code>addr ≡ 0 (mod N)</code>。未对齐时，访问可能跨缓存行甚至跨页：一次逻辑 load 变成两次翻译、两次填充。<a href="/cs/riscv-compressed">压缩指令</a> 已要求 16 位取指对齐；数据侧同类问题更大，因为 <code>ld</code> 是 8 字节。</p><p><span class="marginnote">数字实例：8 字节的 <code>double</code> 要求地址是 8 的倍数——0x1000 合法，0x1004 非对齐。若 64 字节缓存行从 0x1000 开始，0x1004 起的 8 字节落在偏移 60–67，横跨行尾：硬件得先取这一行拿前 4 字节，再取下一行拿后 4 字节，一次访存变两拍。</span></p><p>x86：普通访存允许非对齐，罚的是周期；<code>EFLAGS.AC</code> 可打开对齐检查。A64：普通内存上多数 load/store 可非对齐；独占监视器与部分设备内存更严。RISC-V：实现可硬件处理、可 trap 到 M 态模拟，规范不强制同一种性能。缺口不是端序，而是<strong>这条路径在手册里是否合法、是否原子</strong>。</p><p><a href="/cs/lr-sc-cas">LR/SC 与 CAS</a> 通常要求自然对齐，否则保留集与缓存行排他没有定义。SSE 的 <code>movaps</code> 要求 16 字节；<code>movups</code> 才放松——<a href="/cs/simd-extensions">SIMD</a> 把对齐写进助记符。</p><h3 id="对齐不是「编译器多插几个-nop」" tabindex="-1">对齐不是「编译器多插几个 nop」 <a class="header-anchor" href="#对齐不是「编译器多插几个-nop」" aria-label="Permalink to &quot;对齐不是「编译器多插几个 nop」&quot;">​</a></h3><p>指令对齐影响取指打包；数据对齐影响 ABI 的 <code>alignof</code> 与结构体填充。把两者混成「好看」，栈上 <code>double</code> 未按 ABI 对齐时，AAPCS/SysV 直接未定义或罚崩。</p><p><span class="marginnote">常见误区：初学者以为非对齐访问一定会「报错」。实际上同一份代码在 x86 上多半默默执行、只是多罚几个周期；换到某些 RISC-V 实现就 trap 进固件模拟，再换到 SIMD 的 <code>movaps</code> 或原子指令则直接非法。对齐行为是 ISA 合同的一部分，不是普适运行时错误。</span></p><p><span class="marginnote">RISC-V 非特权手册的 misaligned。ARM ARM 的 Alignment fault。Intel SDM 的 Alignment Check 与非对齐惩罚。CA:AQA 用对齐解释缓存与总线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器按 ABI 给标量与结构体填填充字节；packed 结构显式放弃对齐，生成字节拼装或非对齐 load。内核与驱动访问 MMIO 必须用架构允许的宽度与对齐，否则设备与总线协议先坏。跨页非对齐：可能两次缺页，<a href="/cs/sv39-page-table">Sv39</a> 走访两次。</p>',14)),(s(),t(l,null,{default:A(()=>[r(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E6%9C%89%E6%95%88%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20OK%7B%22%E8%87%AA%E7%84%B6%E5%AF%B9%E9%BD%90%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20ONE%5B%22%E4%B8%80%E6%AC%A1%E7%BF%BB%E8%AF%91%E4%B8%8E%E4%B8%80%E6%AC%A1%E5%A1%AB%E5%85%85%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20SPLIT%5B%22%E6%8B%86%E8%AE%BF%E9%97%AE%E6%88%96%20trap%22%5D%0A%20%20SPLIT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AABI%20%E6%8A%8A%E5%AF%B9%E9%BD%90%E5%86%99%E6%88%90%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与 "),E("a",{href:"/cs/fence-instructions"},"fence"),e("：拆成两次的 store 之间仍受内存模型约束；不能假设设备看见一次原子字写。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("ISA 对照单元快结束：编码、特权、向量、端序、对齐都是硬件保证的边界。软件还要在这些边界上叠一层"),E("strong",null,"调用约定与目标文件合同"),e("——同一颗核、同一 ISA，SysV 与 Windows x64 仍不能互调。下一课把 ISA 收成 ABI 边界，并交给微结构进阶：前端看到的分支，是编译器按这份合同发出来的。")],-1)),a[6]||(a[6]=E("p",null,"一条非对齐 load 在硬件里到底经历了什么？以跨缓存行的 8 字节读为例：",-1)),(s(),t(l,null,{default:A(()=>[r(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22ld%20%E8%AF%BB%208%20%E5%AD%97%E8%8A%82%EF%BC%8C%E5%9C%B0%E5%9D%80%E8%90%BD%E5%9C%A8%E8%A1%8C%E5%81%8F%E7%A7%BB%2060%22%5D%20--%3E%20CHK%7B%22%E5%9C%B0%E5%9D%80%E6%98%AF%208%20%E7%9A%84%E5%80%8D%E6%95%B0%E5%90%97%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E4%B8%8D%E6%98%AF%EF%BC%9A%E8%B7%A8%E8%A1%8C%22%7C%20TWO%5B%22%E6%8B%86%E4%B8%A4%E6%AC%A1%E8%AE%BF%E5%AD%98%EF%BC%9A%E6%9C%AC%E8%A1%8C%E5%B0%BE%204%20%E5%AD%97%E8%8A%82%20%2B%20%E4%B8%8B%E4%B8%80%E8%A1%8C%E5%A4%B4%204%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20TWO%20--%3E%20MERGE%5B%22%E7%A1%AC%E4%BB%B6%E6%8A%8A%E4%B8%A4%E6%AE%B5%E6%8B%BC%E5%9B%9E%208%20%E5%AD%97%E8%8A%82%E7%BB%99%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20MERGE%20--%3E%20COST%5B%22%E5%A4%9A%E8%8A%B1%E8%8A%82%E6%8B%8D%EF%BC%8C%E4%B8%94%E5%AF%B9%E5%85%B6%E4%BB%96%E6%A0%B8%E4%B8%8D%E5%86%8D%E5%8E%9F%E5%AD%90%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20ONE%5B%22%E5%8D%95%E6%AC%A1%E7%BC%93%E5%AD%98%E8%A1%8C%E8%AE%BF%E9%97%AE%EF%BC%8C%E4%BF%9D%E6%8C%81%E5%8E%9F%E5%AD%90%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">直觉类比：缓存行像传送带上 64 字节一格的整箱——总线一次只能搬整箱。对齐的数据完整躺在一箱里，伸手一次拿到；非对齐的数据骑在两箱的接缝上，只能先开这箱取一半、再开下箱取另一半，然后自己拼起来，力气（周期）花了两倍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 MMIO 设备的访问宽度表抄来，不保证软模拟非对齐的延迟。不进入数据库列存的对齐 SIMD 作业全文。</p><p>后课默认：原子与许多 SIMD 要自然对齐；普通标量在 x86/A64 上常可非对齐但有代价；RISC-V 实现可选 trap。下一课 ISA 作为 ABI 边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自然对齐服务单次缓存行与原子性。</li><li>非对齐：硬件拆、trap，或指令直接不允许。</li><li>端序与对齐是两件独立的 ISA 事实。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const f=d(p,[["render",c]]);export{u as __pageData,f as default};
